// Fixture 4: five Node core APIs behaving together in one process.
//
// Each marker is printed only after the API has actually DONE something: a file is written, read back and removed; a
// server binds a port and emits its lifecycle events; two chunks travel through a real Transform into a real Writable;
// a timer fires and its elapsed time is measured against the virtual clock; an emitter runs a listener, a once-only
// listener, and then proves removeListener worked. Nothing here prints a marker on the strength of an import alone,
// because an import that succeeds and an API that behaves are exactly the two things this fixture exists to separate.
//
// The chain is sequential and event-driven rather than a promise chain: a marker that never appears then means the
// previous step hung or threw, which is the liveness reading the fixture's knownLimits describes.

import fs from "node:fs";
import http from "node:http";
import { EventEmitter } from "node:events";
import { Readable, Transform, Writable, pipeline } from "node:stream";

/** Reports a failed check and stops the chain, so later markers are absent rather than falsely printed. */
function fail(name, detail) {
  console.error("core-check failed: " + name + ": " + detail);
}

function report(marker) {
  console.log(marker);
}

// ---------------------------------------------------------------- filesystem
function checkFilesystem(next) {
  try {
    const file = "core-note.txt";
    const dir = "core-dir";

    fs.writeFileSync(file, "hello node core\n");
    const contents = fs.readFileSync(file, "utf8");
    if (contents !== "hello node core\n") throw new Error("read back " + JSON.stringify(contents));

    const size = fs.statSync(file).size;
    if (size !== "hello node core\n".length) throw new Error("stat size " + size);

    fs.mkdirSync(dir);
    fs.renameSync(file, dir + "/note.txt");
    const entries = fs.readdirSync(dir);
    if (entries.indexOf("note.txt") === -1) throw new Error("rename did not land: " + entries.join(","));

    fs.unlinkSync(dir + "/note.txt");
    fs.rmdirSync(dir);
    if (fs.existsSync(file) || fs.existsSync(dir)) throw new Error("cleanup left something behind");

    report("fs-ok");
    next();
  } catch (error) {
    fail("filesystem", error && error.message ? error.message : String(error));
  }
}

// ---------------------------------------------------------------------- http
function checkHttp(next) {
  const port = 4123;
  const server = http.createServer(function (request, response) {
    // Registered to prove the handler is wired to this server; the fixture has no client, so it is not invoked here.
    response.writeHead(200, { "content-type": "text/plain" });
    response.end("pong");
  });

  let listeningSeen = false;
  server.once("listening", function () {
    listeningSeen = true;
  });

  try {
    server.listen(port);
  } catch (error) {
    fail("http", (error && error.message) || String(error));
    return;
  }

  // Node binds synchronously and emits `listening` on a later tick; both halves are checked here.
  if (server.listening !== true) {
    fail("http", "server did not report listening after listen()");
    return;
  }
  const address = server.address();
  if (address === null || address.port !== port) {
    fail("http", "address() was " + JSON.stringify(address));
    return;
  }

  server.close(function () {
    // `close` fires on a later tick too, so this callback also proves the asynchronous lifecycle is intact.
    if (listeningSeen !== true) {
      fail("http", "the listening event never fired");
      return;
    }
    if (server.listening !== false) {
      fail("http", "server still listening after close()");
      return;
    }
    report("http-ok");
    next();
  });
}

// ------------------------------------------------------------------- streams
function checkStreams(next) {
  const collected = [];
  const upper = new Transform({
    transform: function (chunk, encoding, callback) {
      callback(null, String(chunk).toUpperCase());
    },
  });
  const sink = new Writable({
    write: function (chunk, encoding, callback) {
      collected.push(String(chunk));
      callback();
    },
  });

  pipeline(Readable.from(["node ", "core"]), upper, sink, function (error) {
    if (error) {
      fail("streams", (error && error.message) || String(error));
      return;
    }
    const text = collected.join("");
    if (text !== "NODE CORE") {
      fail("streams", 'collected ' + JSON.stringify(text));
      return;
    }
    report("stream-ok");
    next();
  });
}

// -------------------------------------------------------------------- timers
function checkTimers(next) {
  const startedAt = Date.now();
  const perfStartedAt = performance.now();

  setTimeout(function () {
    const elapsed = Date.now() - startedAt;
    if (elapsed !== 25) {
      fail("timers", "first timer measured " + elapsed + " ms of virtual time, expected 25");
      return;
    }

    // A chained timer: the total is the sum of both delays, which only holds if the clock advances properly between them.
    setTimeout(function () {
      const total = Date.now() - startedAt;
      const perfElapsed = performance.now() - perfStartedAt;
      if (total !== 40) {
        fail("timers", "chained timer measured " + total + " ms in total, expected 40");
        return;
      }
      if (perfElapsed < 40) {
        fail("timers", "performance.now() advanced only " + perfElapsed + " ms");
        return;
      }
      report("timer-ok");
      next();
    }, 15);
  }, 25);
}

// -------------------------------------------------------------------- events
function checkEvents(next) {
  try {
    const emitter = new EventEmitter();
    const seen = [];

    const onFirst = function (value) {
      seen.push("first:" + value);
    };
    const onSecond = function (value) {
      seen.push("second:" + value);
    };

    emitter.on("tick", onFirst);
    emitter.on("tick", onSecond);
    emitter.once("tick", function (value) {
      seen.push("once:" + value);
    });

    // Two listeners fire in registration order, then the once-only listener fires exactly once.
    if (emitter.emit("tick", 1) !== true) throw new Error("emit reported no listeners");

    emitter.removeListener("tick", onFirst);
    const remaining = emitter.listenerCount("tick");
    if (remaining !== 1) throw new Error("listenerCount after removeListener was " + remaining);

    // The removed listener stays silent and the once-only listener does not fire again.
    emitter.emit("tick", 2);

    const expected = "first:1,second:1,once:1,second:2";
    const observed = seen.join(",");
    if (observed !== expected) throw new Error("listeners saw " + observed + ", expected " + expected);

    report("events-ok");
    next();
  } catch (error) {
    fail("events", error && error.message ? error.message : String(error));
  }
}

const checks = [checkFilesystem, checkHttp, checkStreams, checkTimers, checkEvents];

function run(index) {
  if (index >= checks.length) return;
  checks[index](function () {
    run(index + 1);
  });
}

run(0);
